    def retry_delay(response, attempt)
      fallback = [@retry_max_delay, @retry_base_delay * (2.0**[attempt - 1, 20].min)].min
      value = response['retry-after-ms'] if response.respond_to?(:[])
      if value && value.match?(/\A\d+(?:\.\d+)?\z/)
        return [@retry_max_delay, value.to_f / 1000.0].min
      end

      value = response['Retry-After'] if response.respond_to?(:[])
      return fallback unless value
      if value.match?(/\A\d+(?:\.\d+)?\z/)
        return [@retry_max_delay, value.to_f].min
      end

      begin
        require 'time'
        [[Time.httpdate(value) - Time.now, 0].max, @retry_max_delay].min
      rescue ArgumentError
        fallback
      end
    end

    def check_cancellation(cancelled = @cancelled)
      raise PoolsterCancellationError, 'request cancelled' if cancelled && cancelled.call
    end

    def retry_pause(delay, cancelled = @cancelled)
      deadline = Process.clock_gettime(Process::CLOCK_MONOTONIC) + delay
      loop do
        check_cancellation(cancelled)
        remaining = deadline - Process.clock_gettime(Process::CLOCK_MONOTONIC)
        break if remaining <= 0

        sleep [remaining, 0.05].min
      end
    end

    def execute_with_retry(handler, request, idempotency_header, cancelled: @cancelled)
      method = request.method.upcase
      key = request[idempotency_header || 'Idempotency-Key']
      replay_safe = %w[GET HEAD OPTIONS TRACE QUERY PUT
                       DELETE].include?(method) || (%w[POST PATCH].include?(method) && key && !key.strip.empty?)
      provider = request["Authorization"] ? nil : @token_provider
      token = provider && provider.token(cancelled: cancelled)
      request["Authorization"] = "Bearer #{token}" if token
      refreshed = false
      attempt = 0
      loop do
        check_cancellation(cancelled)
        attempt += 1
        begin
          response = handler.call(request)
        rescue PoolsterTimeoutError
          raise
        rescue IOError, EOFError, SystemCallError, Timeout::Error
          raise unless replay_safe && attempt < @max_attempts

          retry_pause([@retry_max_delay, @retry_base_delay * (2.0**[attempt - 1, 20].min)].min, cancelled)
          next
        end
        if response.code.to_i == 401 && provider && replay_safe && !refreshed
          refreshed = true
          token = provider.token(rejected_token: token, cancelled: cancelled)
          request["Authorization"] = "Bearer #{token}"
          attempt -= 1
          next
        end
        return response unless replay_safe && attempt < @max_attempts && [408, 429, 500, 502, 503,
                                                                          504].include?(response.code.to_i)

        retry_pause(retry_delay(response, attempt), cancelled)
      end
    end
    private

    def poolster_parameter_content(value, content_type)
      return JSON.generate(Models.to_wire(value)) if content_type == 'application/json' || content_type.end_with?('+json')
      return URI.encode_www_form(value) if content_type == 'application/x-www-form-urlencoded' && value.is_a?(Hash)
      raise ArgumentError, 'parameter content must be a serialized string' unless value.is_a?(String)

      value
    end

    def poolster_whole_query(value, content_type, allow_null = false)
      return '' if value.nil? && !allow_null
      if content_type == 'application/json' || content_type.end_with?('+json')
        return URI.encode_www_form_component(JSON.generate(Models.to_wire(value)))
      end

      return URI.encode_www_form(value.flat_map { |key, item|
        Array(item).map { |part|
          [key, part]
        }
      }) if value.is_a?(Hash) && content_type == 'application/x-www-form-urlencoded'
      raise ArgumentError, 'whole query must be a serialized string' unless value.is_a?(String)

      value = value.sub(/\A\?/, '')
      raise ArgumentError, 'unsafe whole query' if value.match?(/[?#\r\n]/)

      value
    end

    def poolster_sequential_json(body, content_type)
      raise ArgumentError, 'sequential response exceeds 64 MiB' if body.bytesize > 64 * 1024 * 1024

      if content_type == 'application/json-seq'
        prefix, *records = body.split("\x1e", -1)
        raise JSON::ParserError,
              'JSON sequence requires record separators' unless prefix.strip.empty? && (body.strip.empty? || !records.empty?)

        records.map { |record| JSON.parse(record) }
      else
        body.lines.reject { |line| line.strip.empty? }.map { |line| JSON.parse(line) }
      end
    end

    def request(method, path, query:, headers:, body:, response_schemas: nil, idempotency_header: nil,
                request_options: nil, multipart: false)
      options = request_options || {}
      raise ArgumentError, 'request_options must be a Hash' unless options.is_a?(Hash)
      raise ArgumentError, 'unknown request option' unless (options.keys - [:headers, :timeout, :cancelled]).empty?

      timeout = options.fetch(:timeout, @timeout)
      raise ArgumentError,
            'timeout must be a finite positive number' unless timeout.is_a?(Numeric) && timeout.finite? && timeout > 0

      supplied_headers = options.fetch(:headers, {})
      raise ArgumentError, 'headers must be a Hash' unless supplied_headers.is_a?(Hash)

      supplied_cancelled = options[:cancelled]
      raise ArgumentError, 'cancelled must be callable' if supplied_cancelled && !supplied_cancelled.respond_to?(:call)

      cancelled = -> { (@cancelled && @cancelled.call) || (supplied_cancelled && supplied_cancelled.call) }
      check_cancellation(cancelled)
      uri = URI.join(@base_url + "/", path.sub(%r{^/}, ""))
      uri.query = query.is_a?(String) ? query : URI.encode_www_form(query) unless query.empty?
      request = if %w[GET HEAD POST PUT DELETE OPTIONS TRACE
                      PATCH].include?(method.upcase) && Net::HTTP.const_defined?(method.capitalize, false)
                  Net::HTTP.const_get(method.capitalize, false).new(uri)
                else
                  Net::HTTPGenericRequest.new(method, !body.nil?, method != "HEAD", uri)
                end
      merged_headers = @headers.merge(headers).merge(supplied_headers.transform_keys(&:to_s))
      merged_headers.each { |key, value| request[key] = value }
      request["Authorization"] ||= "Bearer #{@bearer_token}" if @bearer_token
      request["X-API-Key"] ||= @api_key if @api_key
      if body.is_a?(MultipartBody)
        raise ArgumentError, 'operation does not accept multipart/form-data' unless multipart

        request["Content-Type"], request.body = body.encode
      elsif !body.nil?
        request["Content-Type"] ||= "application/json"
        request.body = body.is_a?(String) ? body : JSON.generate(body.respond_to?(:to_h) ? body.to_h : body)
      end
      handler = @transport || lambda do |native_request|
        target = native_request.uri || uri
        Net::HTTP.start(target.hostname, target.port, use_ssl: target.scheme == "https", open_timeout: timeout, read_timeout: timeout) { |http| http.request(native_request) }
      end
      @middleware.reverse_each do |item|
        following = handler
        handler = ->(native_request) { item.call(native_request, following) }
      end
      response = Timeout.timeout(timeout, PoolsterTimeoutError) {
        execute_with_retry(handler, request, idempotency_header, cancelled: cancelled)
      }
      content_type = (response.respond_to?(:content_type) ? response.content_type : (response["Content-Type"] rescue nil)).to_s.split(
        ';', 2
      ).first
